function OverseaManageFastSellingPopup:RefreshShow()
    local costNum = self:GetCostNum()
    local str = localize("_num1_张售卖卷可快速售卖_num2_份套餐",{_num1_ = string.format("<color=#FE4CBB>%s</color>",1),_num2_ = string.format("<color=#FE4CBB>%s</color>",costNum)})
    CfUtils.FillText(self.TextNumber1,str)

    local haveNum =  GoodsUtils.GetThingNo(self:GetCostId())
    local needNum = math.ceil(self.parameters.maxNum/costNum)
    local norNum = haveNum >= needNum and needNum * costNum or haveNum * costNum
    norNum = math.min(needNum,haveNum)
    self.sliderEnv:RefreshNode(
            norNum,
            self.saleNum,
            needNum,
            Bind(self, self.SliderOnValueChangedHandler)
    )



    if self.CommonBtnConsumePop then
        self.costNum = needNum >= haveNum and (haveNum == 0 and 1 or haveNum) or needNum
        UICommonUtils.FillCommonBtnConsumePop(self.CommonBtnConsumePop,  checkNumber(MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(43).num), self.costNum)
    end
end

function OverseaManageFastSellingPopup:SliderOnValueChangedHandler(value)
    local num = math.min(self.parameters.maxNum,value * self:GetCostNum())
    self.sliderEnv:SetTextNumber(num)
    self.saleNum = num
    self.costNum = value
    UICommonUtils.FillCommonBtnConsumePop(self.CommonBtnConsumePop,  self:GetCostId(),self.costNum )
end

function OverseaManageFastSellingPopup:GetCostNum()
    local costId = self:GetCostId()
    local costVo = GoodsConfMgr:GetInstance():GetGoodsVoById(costId)
    local costNum = costVo.effectNum
    return checkNumber(costNum)
end

function OverseaManageFastSellingPopup:GetCostId()
    return checkNumber(MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(43).num)
end

