end

function OverseaManageFastSellingPopup:OnBtnCloseClick()
    UIModule.CloseDialog(self.controller)
end

function OverseaManageFastSellingPopup:OnBtnSureClick()
    local haveNum = GoodsUtils.GetThingNo(self:GetCostId())
    if haveNum >= self.costNum then
        GameUtils.Request(Interfaces.MaidCoffeeMenuQuickSale,{menuId = self.parameters.curIndex ,saleNum = self.saleNum},function(request,response)
            if response.errCode == 0  then
                local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
                local maidCoffeeHomeDojo = maidCoffeeComponent:GetMaidCoffeeHomeDoJo()
                ---@type MaidCoffeeMgr
                --local MaidCoffeeMgr = import('Game.MaidCoffee.MaidCoffeeMgr')
                --MaidCoffeeMgr:GetInstance():RemoveTimer()
                maidCoffeeHomeDojo:UpdateMenuData(self.parameters.curIndex,response.data.menus[self.parameters.curIndex])
                --MaidCoffeeMgr:GetInstance():StartMenuTimer()
                --maidCoffeeComponent:RefreshMenuRedPoint()
                GoodsUtils.ConsumeGoods(response.data.consume)
                GameUtils.Toast(localize("已快速售卖_num_份",{_num_ = self.saleNum}))
                Events.Broadcast(Constants.EventNames.MaidCoffeeQuickSaleSuccess)
                self:OnBtnCloseClick()
            end
        end)
    else
        GoodsUtils.ShowCommonLackMaterialDialog({{goodsId = self:GetCostId(), num = self.costNum - haveNum }})
    end
end

return OverseaManageFastSellingPopup